extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var walls := find_by_name(main, "Walls") as TileMapLayer
	if not check("walls", walls != null, "Nella scena serve il nodo Walls"):
		return
	var cell_tile: Vector2i = walls.get_cell_atlas_coords(Vector2i(10, 10))
	check("cell_painted", cell_tile == Vector2i(3, 0), "La cella (10, 10) di Walls deve contenere la tessera (3, 0) (trovata %s)" % str(cell_tile))
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("player", player != null, "Nella scena deve esserci il Player"):
		return
	player.position = Vector2(168, 200)
	await hold_action("move_up", 30)
	check("wall_solid", player.position.y > 175.0, "Il personaggio deve fermarsi contro il muro a tessere e non attraversarlo (Y = %.1f)" % player.position.y)

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var ground := find_by_name(main, "Ground") as TileMapLayer
	var dec := find_by_name(main, "Decoration") as TileMapLayer
	if not check("nodes", ground != null and dec != null, "Servono i nodi Ground e Decoration"):
		return
	check("ground_corner", ground.get_cell_atlas_coords(Vector2i(5, 5)) == Vector2i(2, 0) and ground.get_cell_atlas_coords(Vector2i(15, 15)) == Vector2i(2, 0), "Ground deve avere la tessera (2, 0) negli angoli (5,5) e (15,15)")
	check("dec_7_7", dec.get_cell_atlas_coords(Vector2i(7, 7)) == Vector2i(2, 1), "Decoration deve avere la tessera (2, 1) in (7, 7)")
	check("dec_12_12", dec.get_cell_atlas_coords(Vector2i(12, 12)) == Vector2i(2, 1), "Decoration deve avere la tessera (2, 1) in (12, 12)")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var ground := find_by_name(main, "Ground") as TileMapLayer
	var walls := find_by_name(main, "Walls") as TileMapLayer
	var dec := find_by_name(main, "Decoration") as TileMapLayer
	var player := find_by_name(main, "Player") as CharacterBody2D
	if not check("nodes", ground != null and walls != null and dec != null and player != null, "Tutti i nodi richiesti devono essere presenti nella scena"):
		return

	var ground_ok := true
	for x in range(10):
		for y in range(10):
			if ground.get_cell_atlas_coords(Vector2i(x, y)) != Vector2i(2, 0):
				ground_ok = false
				break
	check("ground_grid", ground_ok, "Il pavimento Ground deve avere tessere (2,0) per l'intera griglia da (0,0) a (9,9)")

	var walls_ok := true
	for x in range(10):
		for y in range(10):
			var expected := Vector2i(-1, -1)
			if (x == 0 or x == 9 or y == 0 or y == 9) and not (x == 5 and y == 9):
				expected = Vector2i(3, 0)
			if walls.get_cell_atlas_coords(Vector2i(x, y)) != expected:
				walls_ok = false
				break
	check("walls_perim", walls_ok, "I muri su Walls devono coprire il perimetro lasciando libero solo il varco in (5,9)")
	check("dec_tile", dec.get_cell_atlas_coords(Vector2i(3, 3)) == Vector2i(2, 1), "La decorazione (2,1) deve trovarsi esattamente nella cella (3,3)")
	check("player_pos", player.position == Vector2(80, 80), "La posizione del Player deve essere Vector2(80, 80) (trovata %s)" % str(player.position))
